CREATE TABLE trg17_products (product_id INTEGER PRIMARY KEY, product_name TEXT NOT NULL, price INTEGER NOT NULL);
CREATE TABLE trg17_price_audit (audit_id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL, old_price INTEGER NOT NULL, new_price INTEGER NOT NULL);
INSERT INTO trg17_products VALUES (1, 'Notebook', 40);
CREATE TRIGGER trg17_price_update AFTER UPDATE OF price ON trg17_products WHEN OLD.price IS NOT NEW.price BEGIN INSERT INTO trg17_price_audit(product_id, old_price, new_price) VALUES (OLD.product_id, OLD.price, NEW.price); END;
UPDATE trg17_products SET price = 55 WHERE product_id = 1;
SELECT product_id, old_price, new_price FROM trg17_price_audit;

